String jobNameForLogging = graph.getJobName();
// Mask phone numbers (ASCII 010 followed by eight digits) for external diagnostics
if (jobNameForLogging != null && jobNameForLogging.startsWith("010") && jobNameForLogging.length() > 8) {
    String masked = "010" + "*******";
    org.slf4j.LoggerFactory.getLogger("csi.route.b").info("Job context: {}", masked);
} else {
    org.slf4j.LoggerFactory.getLogger("csi.route.b").info("Job context: {}", jobNameForLogging);
}
